# Crop real page captures into clippings (crops only, nothing altered) + highlight boxes (clip px). Writes assets/src/*.png + clips.js
import json, os
from PIL import Image
P = os.path.abspath(os.path.join(os.path.dirname(__file__), '..')); O = os.path.join(P, 'assets/src'); os.makedirs(O, exist_ok=True)
OLD = os.path.join(P, '../film/stills/directions/_src/caps'); NEW = os.path.join(P, 'assets/caps')
def clip(name, d, img, box, hls, source, url):
    x0, y0, x1, y1 = box; Image.open(os.path.join(d, img)).convert('RGB').crop(box).save(os.path.join(O, name + '.png'))
    return name, {'w': x1 - x0, 'h': y1 - y0, 'hl': [[a - x0, b - y0, c, d_] for a, b, c, d_ in hls], 'source': source, 'url': url}
RFC = 'https://www.rfc-editor.org/rfc/rfc9110.html'
out = dict([
  clip('rfc-first', OLD, 'rfc9110__the-first-digit-of-the-s.png', (110, 590, 1230, 1060), [[124, 778, 610, 34]], 'RFC 9110 · HTTP Semantics · §15', RFC + '#name-status-codes'),
  clip('gh-404', OLD, 'github__to-avoid-confirming-the-.png', (405, 605, 1515, 820), [[600, 780, 735, 34]], 'GitHub Docs · Troubleshooting the REST API', 'https://docs.github.com/en/rest/using-the-rest-api/troubleshooting-the-rest-api'),
  clip('gh-line', OLD, 'github__to-avoid-confirming-the-.png', (405, 738, 1515, 818), [[600, 780, 735, 34]], 'GitHub Docs · Troubleshooting the REST API', 'https://docs.github.com/en/rest/using-the-rest-api/troubleshooting-the-rest-api'),
  clip('google-4xx', OLD, 'google__are-treated-the-same.png', (820, 768, 1580, 1150), [[1060, 776, 460, 34], [828, 1046, 196, 34], [828, 1113, 134, 34]], 'Google Search Central · HTTP status codes', 'https://developers.google.com/search/docs/crawling-indexing/http-network-errors'),
  clip('google-line', OLD, 'google__are-treated-the-same.png', (1052, 770, 1528, 812), [[1060, 776, 460, 34]], 'Google Search Central · HTTP status codes', 'https://developers.google.com/search/docs/crawling-indexing/http-network-errors'),
  clip('gh-hl', OLD, 'github__to-avoid-confirming-the-.png', (588, 770, 1348, 820), [[600, 780, 735, 34]], 'GitHub Docs · Troubleshooting the REST API', 'https://docs.github.com/en/rest/using-the-rest-api/troubleshooting-the-rest-api'),
  clip('rfc-301', NEW, 'rfc9110b__request-method-from-post.png', (483, 768, 1140, 820), [[485, 776, 646, 36]], 'RFC 9110 · §15.4.2 301 Moved Permanently', RFC + '#name-301-moved-permanently'),
  clip('rfc-401', NEW, 'rfc9110b__lacks-valid-authenticati.png', (120, 720, 1205, 880), [[1028, 778, 134, 36], [124, 812, 262, 36]], 'RFC 9110 · §15.5.2 401 Unauthorized', RFC + '#name-401-unauthorized'),
  clip('laravel-false', NEW, 'laravel__you-risk-exposing.png', (630, 728, 1360, 822), [[1000, 734, 326, 40], [638, 778, 184, 40]], 'Laravel 12.x docs · Error Handling', 'https://laravel.com/docs/12.x/errors#configuration'),
  clip('rfc-teapot', NEW, 'rfc2324__i-m-a-teapot.png', (0, 630, 880, 900), [[78, 776, 196, 30]], 'RFC 2324 · Hyper Text Coffee Pot Control Protocol · 1 April 1998', 'https://www.rfc-editor.org/rfc/rfc2324.html'),
])
json.dump(out, open(os.path.join(O, 'clips.json'), 'w'), indent=1)
open(os.path.join(O, 'clips.js'), 'w').write('/* generated by talking-head/tools/clips.py: real page clippings (crops only) + highlight boxes in clip px */\nconst CLIPS = ' + json.dumps(out) + ';\n')
print(list(out))
